"""Auto-generated court scraper — SELF-CONTAINED pure Playwright (no external deps).
Generated by scrape_generator for: https://justicecourts.maricopa.gov/app/courtrecords/CaseSearch
Contract v2: preprocess(inputs) -> params; scrape(page, params) -> dict.
scrape navigates to the case detail page and EXTRACTS the target fields (no run-time LLM),
returning a dict of RESULT_FIELDS plus a "_raw_text" fallback dump."""
from __future__ import annotations

import re
from playwright.sync_api import Page

CONTRACT_VERSION = '2'
_DEFAULT_URL = 'https://justicecourts.maricopa.gov/app/courtrecords/CaseSearch'
RESULT_FIELDS = [
    'caseNumber',
    'defendantFullName',
    'defendantAddress',
    'defendantCityState',
    'defendantZip',
    'courtName',
    'courtState',
    'filingDate',
    'plaintiffName',
    'judgement',
    'judgementAmount',
    'judgementDate',
    'judgementRelDate',
    'relatedCaseNumbers',
]
def _canon(s):
    """Alphanumerics only, uppercased. 'gv24-001234' -> 'GV24001234'."""
    return re.sub(r"[^A-Za-z0-9]", "", s or "").upper()


def _format_like(case_raw, example):
    """Reinsert the separators of `example` into canon `case_raw`."""
    out, i = [], 0
    for ch in (example or ""):
        if ch.isalnum():
            if i < len(case_raw):
                out.append(case_raw[i]); i += 1
        else:
            out.append(ch)
    if i < len(case_raw):
        out.append(case_raw[i:])
    return "".join(out)


def _settle(page):
    try:
        page.wait_for_load_state("domcontentloaded", timeout=15000)
    except Exception:
        pass
    # Wait out a transient anti-bot interstitial (e.g. AWS WAF "Human Verification"): the remote
    # browser solves it server-side, but the solve time VARIES a lot (~3s to well over a minute), so
    # be patient — bailing early makes the next action fire on the challenge page and time out. Waits
    # up to ~150s. No-op on normal pages (returns on the first check).
    _markers = ("human verification", "verify you are human", "confirm you are human",
                "security check", "checking your browser", "verificación humana",
                "comprueba que eres", "select all images", "press and hold")
    cleared = True
    for _ in range(75):
        try:
            t = (page.title() or "").lower()
            body = (page.evaluate("() => (document.body && document.body.innerText || '').slice(0, 500)") or "").lower()
        except Exception:
            break
        blob = t + " " + body
        if not any(mk in blob for mk in _markers):
            break
        cleared = False
        try:
            page.wait_for_timeout(2000)
        except Exception:
            break
    else:
        cleared = False
    # After a challenge clears, the SPA (re)renders its content — give the network a moment to idle
    # so the search form / detail content is present before the next action reads it.
    if not cleared:
        try:
            page.wait_for_load_state("networkidle", timeout=10000)
        except Exception:
            pass


def _goto(page, url):
    """Resilient navigation. Uses wait_until='commit' (fires the instant the response starts) and
    treats a timeout as non-fatal, because an anti-bot challenge (e.g. AWS WAF) can STALL the
    navigation so 'load'/'domcontentloaded' never fire and a plain goto hangs the full timeout. After
    the (possibly partial) navigation, _settle() waits out the challenge and for the DOM to be ready."""
    try:
        page.goto(url, wait_until="commit", timeout=45000)
    except Exception:
        pass
    _settle(page)
    return page


def _solve_captcha(page, page_url, api_key):
    """If a reCAPTCHA gates this page, solve it via 2Captcha and inject the token so the form can
    submit. Opt-in + best-effort: no key or no reCAPTCHA -> no-op; any error leaves the page as-is.
    Paid/BrightData browser tiers solve server-side, so this only matters on the free tier. The key
    arrives via params (the gate forbids os), threaded in by the executor from its environment."""
    if not api_key:
        return
    import json
    import time
    import urllib.parse
    import urllib.request
    try:
        found = page.evaluate("""() => {
          const el = document.querySelector('[data-sitekey]');
          let k = el ? el.getAttribute('data-sitekey') : null;
          if (!k) { const f = Array.from(document.querySelectorAll('iframe')).map(i => i.src || '').find(s => s.includes('recaptcha') && s.includes('k=')); if (f) { try { k = new URL(f).searchParams.get('k'); } catch (e) {} } }
          if (!k) return null;
          const ent = !!(window.grecaptcha && window.grecaptcha.enterprise) || Array.from(document.scripts).some(s => (s.src || '').includes('enterprise.js'));
          return {sitekey: k, enterprise: ent};
        }""")
    except Exception:
        return
    if not found or not found.get("sitekey"):
        return
    try:
        q = {"key": api_key, "method": "userrecaptcha", "googlekey": found["sitekey"],
             "pageurl": page_url, "json": 1}
        if found.get("enterprise"):
            q["enterprise"] = 1
        submit = json.loads(urllib.request.urlopen(
            "https://2captcha.com/in.php?" + urllib.parse.urlencode(q), timeout=30).read())
        if submit.get("status") != 1:
            return
        cid, token = submit["request"], None
        time.sleep(15)
        for _ in range(24):
            got = json.loads(urllib.request.urlopen(
                "https://2captcha.com/res.php?" + urllib.parse.urlencode(
                    {"key": api_key, "action": "get", "id": cid, "json": 1}), timeout=30).read())
            if got.get("status") == 1:
                token = got["request"]
                break
            if got.get("request") != "CAPCHA_NOT_READY":
                return
            time.sleep(5)
        if not token:
            return
        page.evaluate("""(t) => {
          let n = 0;
          document.querySelectorAll('textarea[name="g-recaptcha-response"], #g-recaptcha-response').forEach(x => { x.style.display = ''; x.value = t; n++; });
          if (!n) { const ta = document.createElement('textarea'); ta.name = 'g-recaptcha-response'; ta.id = 'g-recaptcha-response'; ta.style.display = 'none'; ta.value = t; document.body.appendChild(ta); }
        }""", token)
    except Exception:
        return


def _loc(page, *candidates):
    """First candidate locator with a (preferably visible) match. POLLS up to ~20s for a candidate
    to appear — the target often renders a beat after navigation (Angular/SPA) or after an anti-bot
    challenge clears, and returning a 0-match locator immediately makes the next action race an
    unready page (e.g. filling a search box that isn't there yet, then submitting empty). Resilient
    fallback chain; returns a best-effort locator if nothing ever matches."""
    for _attempt in range(20):
        fallback = None
        for c in candidates:
            try:
                if c.count() == 0:
                    continue
            except Exception:
                continue
            first = c.first
            try:
                if first.is_visible():
                    return first
            except Exception:
                pass
            if fallback is None:
                fallback = first
        if fallback is not None:
            return fallback
        try:
            page.wait_for_timeout(1000)
        except Exception:
            break
    return candidates[0].first


def _click(page, loc):
    """Click; if it opens a new tab, follow it. Returns the (possibly new) active page."""
    ctx = page.context
    before = len(ctx.pages)
    loc.click()
    _settle(page)
    pages = ctx.pages
    if len(pages) > before:
        np = pages[-1]
        try:
            np.wait_for_load_state("domcontentloaded", timeout=15000)
        except Exception:
            pass
        return np
    return page


def _click_newtab(page, loc):
    """Click a link that opens the detail in a NEW tab, then ADOPT the popup's URL into the CURRENT
    tab: read the popup's url, close the popup, and navigate this tab there. We never switch to the
    popup because observing a 2nd tab hangs on BrightData's CDP browser. Waits for the popup's `page`
    event (expect_page) so an async window.open isn't lost to a race; falls back to a same-tab click
    if no popup appears."""
    ctx = page.context
    try:
        with ctx.expect_page(timeout=12000) as info:
            loc.click()
        np = info.value
        try:
            np.wait_for_load_state("domcontentloaded", timeout=15000)
        except Exception:
            pass
        url = ""
        try:
            url = np.url or ""
        except Exception:
            url = ""
        try:
            np.close()
        except Exception:
            pass
        if url:
            _goto(page, url)
        return page
    except Exception:
        _settle(page)
        return page


def _goto_href(page, loc):
    """Navigate to a link's href in the SAME tab instead of clicking it. Plain links (e.g. the
    case-detail link) land on the exact same page without ever opening a new tab — sidestepping
    popup handling and BrightData's CDP multi-tab hang. Falls back to a normal click (with new-tab
    follow) if the element has no usable http href."""
    href = None
    try:
        href = loc.evaluate(
            "el => { const a = el.closest('a') || (el.tagName === 'A' ? el : null);"
            " return a && a.href ? a.href : null; }"
        )
    except Exception:
        href = None
    if href and isinstance(href, str) and href.lower().startswith(("http://", "https://")):
        return _goto(page, href)
    return _click_newtab(page, loc)


def _fill(page, loc, value):
    """Fill a field, then blur + settle so an SPA (Angular/React) registers the value and enables
    its submit before the next action. Filling and immediately clicking Search runs too fast — the
    framework hasn't bound the value yet, so the search submits empty and stays on the form."""
    loc.fill(str(value))
    try:
        loc.blur()
    except Exception:
        pass
    try:
        page.wait_for_timeout(1200)
    except Exception:
        pass


def _press(page, loc, key):
    """Press a key IN a field (re-focusing it first). _fill blurs the input after filling, so a
    global page.keyboard.press lands on <body> and submits nothing — pressing on the locator
    refocuses the field so Enter actually triggers the form's default submit."""
    try:
        if loc is not None:
            loc.press(key, timeout=8000)
            _settle(page)
            return
    except Exception:
        pass
    try:
        page.keyboard.press(key)
    except Exception:
        pass
    _settle(page)


def _check(page, loc):
    """Select a radio/checkbox robustly. check() auto-waits for actionability and is idempotent
    (re-checking a selected control is a no-op) — far sturdier than a single click() for finicky
    custom radios. Falls back to click() for non-standard widgets that reject check()."""
    try:
        loc.check(timeout=8000)
    except Exception:
        try:
            loc.click(timeout=8000)
        except Exception:
            pass
    _settle(page)


def _select(page, loc, value):
    """Native <select> or type-ahead combobox."""
    try:
        tag = loc.evaluate("el => el.tagName.toLowerCase()")
    except Exception:
        tag = ""
    if tag == "select":
        try:
            loc.select_option(label=str(value)); return
        except Exception:
            pass
        try:
            loc.select_option(str(value)); return
        except Exception:
            pass
    loc.fill(str(value))
    page.wait_for_timeout(800)
    for cand in (page.get_by_role("option", name=str(value), exact=False),
                 page.get_by_role("listitem", name=str(value), exact=False),
                 page.get_by_text(str(value), exact=False)):
        try:
            if cand.count() and cand.first.is_visible():
                cand.first.click(); return
        except Exception:
            continue
    try:
        loc.press("Enter")
    except Exception:
        pass


def _read(page, candidates, strategy="text", attr="", regex=""):
    """Baked field reader: first non-empty value across CSS-selector candidates.

    strategy: "text" -> inner_text; "attr" -> get_attribute(attr). Optional regex post-filter
    (group 1 if present, else whole match). Returns "" if nothing matches (never raises).
    """
    for sel in candidates:
        try:
            loc = page.locator(sel)
            if loc.count() == 0:
                continue
            el = loc.first
            if strategy == "attr" and attr:
                val = el.get_attribute(attr) or ""
            else:
                val = el.inner_text() or ""
            val = val.strip()
            if regex:
                m = re.search(regex, val)
                val = ((m.group(1) if m.groups() else m.group(0)) if m else "").strip()
            if val:
                return val
        except Exception:
            continue
    return ""


def _rx(text, pattern):
    """Pull a value out of accumulated text by regex (group 1 if present, else whole match)."""
    try:
        m = re.search(pattern, text or "")
        if not m:
            return ""
        return (m.group(1) if m.groups() else m.group(0)).strip()
    except Exception:
        return ""


def _inp(params, key):
    """Read a run input by key, CASE-INSENSITIVELY.

    The key spelling is baked in at authoring time — whatever the discovery run happened to call it
    ('DOB') — but a later caller may send 'dob' or 'Dob'. An exact-match dict lookup would return ""
    and the script would search without that identifier, silently, and open the wrong record.
    """
    d = (params or {}).get("inputs") or {}
    if key in d:
        return str(d[key] or "").strip()
    lk = str(key).lower()
    for k, v in d.items():
        if str(k).lower() == lk:
            return str(v or "").strip()
    return ""


def _case_like(v):
    """Does this string look like a case/docket number? 6-30 chars of alnum/dash with >=4 digits."""
    v = (v or "").strip()
    if not (6 <= len(v) <= 30) or not re.fullmatch(r"[A-Za-z0-9-]+", v):
        return False
    return sum(c.isdigit() for c in v) >= 4


def _collect_cases(page, acc):
    """Accumulate case numbers linked from the CURRENT page, in page order, de-duped.

    Called after every navigation step: a party-name search lands on a results list holding EVERY
    case for that person, and the script then opens only one of them. Without this the siblings are
    lost the moment we click through. Prefers the link's visible text (the case number as the court
    prints it) and falls back to a case/docket query parameter in its href.
    """
    try:
        vals = page.evaluate(
            "() => Array.from(document.querySelectorAll('a')).map(a => {"
            "  const t = (a.textContent || '').trim();"
            "  if (t) return t;"
            "  const m = (a.getAttribute('href') || '')"
            "    .match(/[?&][^=]*(?:case|docket)[^=]*=([^&#]+)/i);"
            "  return m ? decodeURIComponent(m[1]) : '';"
            "})"
        ) or []
    except Exception:
        return
    for v in vals:
        v = (v or "").strip()
        if _case_like(v) and v not in acc:
            acc.append(v)


def _click_case_link(page, case_text):
    """Click the link on the CURRENT page whose text is this specific case number, found live on
    the results list — not a pre-recorded, parameterized locator (which would only ever match the
    ONE case number seen during authoring). Returns the (possibly new) active page unchanged if no
    matching link is found, so a caller can just move on to the next case.

    Uses _goto_href (same-tab, popup-safe) rather than the plain _click every other case-detail
    click in this file avoids for the same reason: a second tab hangs BrightData's CDP session and
    would orphan the page.go_back() between loop iterations.
    """
    try:
        loc = page.locator("a", has_text=case_text).first
        if loc.count() == 0:
            return page
        return _goto_href(page, loc)
    except Exception:
        return page


def preprocess(inputs: dict) -> dict:
    """Pure input transforms — no browser."""
    raw = str(inputs.get("case_number", "")).strip()
    return {
        "url": (inputs.get("url") or _DEFAULT_URL),
        "case": raw,
        "case_canon": _canon(raw),
        "court": (inputs.get("court_name") or ""),
        "first_name": (inputs.get("first_name") or ""),
        "last_name": (inputs.get("last_name") or ""),
        "inputs": dict(inputs or {}),
    }


def scrape(page: Page, params: dict) -> dict:
    """Search by name, then open each of the first 10 results found and extract the same fields from each."""
    _last_filled = None
    _seen_cases = []
    _goto(page, params['url'])
    page = _click(page, _loc(page, page.get_by_role('link', name='Name'), page.get_by_text('Name', exact=False)))
    _collect_cases(page, _seen_cases)
    _last_filled = _loc(page, page.locator('[id="MainContent_LastName"]'), page.locator('[name="ctl00$MainContent$LastName"]'), page.get_by_label('Last Name:', exact=False), page.get_by_role('textbox', name='ctl00$MainContent$LastName'))
    _fill(page, _last_filled, _inp(params, 'lastName'))
    _collect_cases(page, _seen_cases)
    _last_filled = _loc(page, page.locator('[id="MainContent_FirstName"]'), page.locator('[name="ctl00$MainContent$FirstName"]'), page.get_by_label('First Name:', exact=False), page.get_by_role('textbox', name='ctl00$MainContent$FirstName'))
    _fill(page, _last_filled, _inp(params, 'firstName'))
    _collect_cases(page, _seen_cases)
    page = _click(page, _loc(page, page.locator('[id="NameSearchlink"]'), page.get_by_role('link', name='Search'), page.get_by_text('Search', exact=False)))
    _collect_cases(page, _seen_cases)
    page = _click(page, _loc(page, page.locator('[id="MainContent_CaseSearchResultsGridView_CaseHyperLink_0"]'), page.get_by_role('link', name='0701TR0303695'), page.get_by_text('0701TR0303695', exact=False)))
    _collect_cases(page, _seen_cases)
    _settle(page)
    try:
        # nav_lines already drilled into one recorded case (needed during
        # authoring to prove reached_detail) -- back out to the results list so
        # every loop iteration below clicks a case fresh from the same start.
        page.go_back()
        _settle(page)
    except Exception:
        pass
    cases = []
    for _case_link in _seen_cases[:10]:
        page = _click_case_link(page, _case_link)
        _settle(page)
        page.wait_for_timeout(1500)  # let SPA detail content render before reading
        case_result = {k: "" for k in RESULT_FIELDS}
        parts = []
        try:
            parts.append(page.locator('main, body').first.inner_text())
        except Exception:
            pass
        raw = "\n\n".join(p for p in parts if p)
        case_result['caseNumber'] = case_result['caseNumber'] or _rx(raw, 'Case Number:\\s*(\\S+)')
        case_result['defendantFullName'] = case_result['defendantFullName'] or _rx(raw, "Defendant\\s*Party Name\\s*([A-Za-z .,'-]+)")
        case_result['courtName'] = case_result['courtName'] or _rx(raw, 'Location:\\s*([A-Za-z ]+)')
        case_result['filingDate'] = case_result['filingDate'] or _rx(raw, 'File Date:\\s*([0-9]{1,2}/[0-9]{1,2}/[0-9]{4})')
        case_result['plaintiffName'] = case_result['plaintiffName'] or _rx(raw, "Plaintiff\\s*Party Name\\s*\\(2\\)\\s*([A-Za-z .,'-]+)")
        if "caseNumber" in RESULT_FIELDS and not case_result.get("caseNumber"):
            case_result["caseNumber"] = _case_link
        case_result["_raw_text"] = raw
        cases.append(case_result)
        try:
            page.go_back()
            _settle(page)
        except Exception:
            pass
    return {"hit": len(cases), "cases": cases}
